  toModifySchema() {
    const hiddenFields = this.hiddenFields;
    return ({ toolSlug, toolkitSlug, schema }: { toolSlug: string; toolkitSlug: string; schema: any }): any => {
      for (const rule of hiddenFields) {
        const toolkitMatches = toolkitSlug?.toLowerCase() === rule.toolkit.toLowerCase();
        const toolMatches = toolSlug?.toLowerCase().includes(rule.tool.toLowerCase());

        if (toolkitMatches && toolMatches) {
          const modifiedSchema = { ...schema };

          if (modifiedSchema.inputParameters) {
            const modifiedInputParameters = { ...modifiedSchema.inputParameters };

            if (modifiedInputParameters.properties) {
