import { Composio } from '@composio/core';
import * as fs from 'fs';

/**
 * SchemaModifier class that allows hiding specific arguments from tool schemas.
 */
class SchemaModifier {
  private hiddenFields: Array<{
    toolkit: string;
    tool: string;
    fields: string[];
  }> = [];

  /**
   * Hide specific fields from a tool's input schema.
   * @param toolkit - The toolkit slug (e.g., 'slack')
   * @param tool - The tool slug portion (e.g., 'chat_post_message')
   * @param fields - Array of field names to hide from the input parameters
   */
  hide(toolkit: string, tool: string, fields: string[]): SchemaModifier {
    this.hiddenFields.push({ toolkit, tool, fields });
    return this;
  }

  /**
   * Returns a modifySchema function compatible with Composio's TransformToolSchemaModifier.
   */
  toModifySchema() {
    const hiddenFields = this.hiddenFields;
    return ({ toolSlug, toolkitSlug, schema }: { toolSlug: string; toolkitSlug: string; schema: any }): any => {
      for (const rule of hiddenFields) {
        const toolkitMatches = (toolkitSlug ?? '').toLowerCase() === rule.toolkit.toLowerCase();
        // Match if the tool slug contains the rule tool substring (case-insensitive)
        const toolMatches = (toolSlug ?? '').toLowerCase().includes(rule.tool.toLowerCase());

        if (toolkitMatches && toolMatches) {
          const modifiedSchema = { ...schema };

          if (modifiedSchema.inputParameters) {
            const modifiedInputParameters = { ...modifiedSchema.inputParameters };

            if (modifiedInputParameters.properties) {
              const modifiedProperties = { ...modifiedInputParameters.properties };
              for (const field of rule.fields) {
                delete modifiedProperties[field];
              }
              modifiedInputParameters.properties = modifiedProperties;

              // Also remove from required list if present
              if (Array.isArray(modifiedInputParameters.required)) {
                modifiedInputParameters.required = modifiedInputParameters.required.filter(
                  (r: string) => !rule.fields.includes(r)
                );
              }

              modifiedSchema.inputParameters = modifiedInputParameters;
            }
          }

          return modifiedSchema;
        }
      }

      return schema;
    };
  }
}

async function main() {
  const composio = new Composio();

  // Create a SchemaModifier to hide the 'text' argument from the Slack post message tool
  const modifier = new SchemaModifier().hide('slack', 'chat_post_message', ['text']);

  // Create a session for 'zealt-user01'
  const session = await composio.create('zealt-user01');
  console.log(`Session created: ${session.sessionId}`);

  // Retrieve the Slack post message tool directly by its slug and apply the schema modifier
  const slackTool = await composio.tools.getRawComposioToolBySlug(
    'SLACK_SENDS_A_MESSAGE_TO_A_SLACK_CHANNEL',
    { modifySchema: modifier.toModifySchema() }
  );

  console.log(`Found tool: ${slackTool.slug}`);
  console.log(
    'Modified inputParameters properties (text field should be absent):',
    Object.keys(slackTool.inputParameters?.properties ?? {})
  );

  // Write the inputParameters to /home/user/schema.json
  const schema = slackTool.inputParameters ?? {};
  fs.writeFileSync('/home/user/schema.json', JSON.stringify(schema, null, 2));
  console.log('Schema written to /home/user/schema.json');
}

main().catch((err) => {
  console.error('Error:', err);
  process.exit(1);
});

